import React from 'react';
import { Routes, Route } from 'react-router-dom';
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import Dashboard from './pages/Dashboard';
import Tournaments from './pages/Tournaments';
import Teams from './pages/Teams';
import Players from './pages/Players';
import Leaderboard from './pages/Leaderboard';
import Fixtures from './pages/Fixtures';
import LiveMatch from './pages/LiveMatch';
import Login from './pages/auth/Login';
// import Signup from './pages/auth/Signup';
import Admin from './pages/admin/Admin';
import ManageMatches from './pages/admin/ManageMatches';
import ManageTeams from './pages/admin/ManageTeams';
import ManagePlayers from './pages/admin/ManagePlayers';
import ManageTournaments from './pages/admin/ManageTournaments';
import ManageLineups from './pages/admin/ManageLineups';
import ManageNews from './pages/admin/ManageNews'; // Admin News
import ManageSponsors from './pages/admin/ManageSponsors'; // Admin Sponsors
import ManageUsers from './pages/admin/ManageUsers'; // Admin User Management
import AuditLogs from './pages/admin/AuditLogs'; // Admin Audit Logs
import ManageGallery from './pages/admin/ManageGallery'; // Admin Gallery Management
import News from './pages/News'; // Public News
import NewsDetail from './pages/NewsDetail'; // Public News Detail
import TournamentDetail from './pages/TournamentDetail';
import PlayerDetail from './pages/PlayerDetail';
import TeamDetail from './pages/TeamDetail';
import Search from './pages/Search';
import Gallery from './pages/Gallery';
import PrivateRoute from './components/common/PrivateRoute';
import { DataProvider } from './context/DataContext';
import { ThemeProvider } from './context/ThemeContext';
import InstallPWA from './components/common/InstallPWA';

function App() {
  return (
    <ThemeProvider>
      <DataProvider>
        <div className="min-h-screen bg-[#0B1220] text-white transition-colors duration-300">
          <Navbar />
          <main className="container mx-auto px-4 py-8">
            <Routes>
              {/* ... routes ... */}
              <Route path="/" element={<Dashboard />} />
              <Route path="/tournaments" element={<Tournaments />} />
              <Route path="/tournaments/:id" element={<TournamentDetail />} />
              <Route path="/search" element={<Search />} />
              <Route path="/teams" element={<Teams />} />
              <Route path="/teams/:id" element={<TeamDetail />} />
              <Route path="/players" element={<Players />} />
              <Route path="/players/:id" element={<PlayerDetail />} />
              <Route path="/fixtures" element={<Fixtures />} />
              <Route path="/leaderboard" element={<Leaderboard />} />
              <Route path="/news" element={<News />} />
              <Route path="/news/:id" element={<NewsDetail />} />
              <Route path="/gallery" element={<Gallery />} />
              <Route path="/live/:matchId" element={<LiveMatch />} />
              <Route path="/login" element={<Login />} />
              {/* <Route path="/signup" element={<Signup />} /> */}

              {/* Admin Routes */}
              <Route
                path="/admin"
                element={
                  <PrivateRoute requireAdminPanelAccess>
                    <Admin />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/matches"
                element={
                  <PrivateRoute requireTeamAdmin>
                    <ManageMatches />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/teams"
                element={
                  <PrivateRoute requireTeamAdmin>
                    <ManageTeams />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/players"
                element={
                  <PrivateRoute requireTeamAdmin>
                    <ManagePlayers />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/lineups/:matchId?/:teamName?"
                element={
                  <PrivateRoute requireTeamAdmin>
                    <ManageLineups />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/tournaments"
                element={
                  <PrivateRoute requireTournamentAdmin>
                    <ManageTournaments />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/news"
                element={
                  <PrivateRoute requireNewsAdmin>
                    <ManageNews />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/sponsors"
                element={
                  <PrivateRoute requireTournamentAdmin>
                    <ManageSponsors />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/users"
                element={
                  <PrivateRoute requireSuperAdmin>
                    <ManageUsers />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/audit-logs"
                element={
                  <PrivateRoute requireSuperAdmin>
                    <AuditLogs />
                  </PrivateRoute>
                }
              />
              <Route
                path="/admin/gallery"
                element={
                  <PrivateRoute>
                    <ManageGallery />
                  </PrivateRoute>
                }
              />
            </Routes>
          </main>
          <InstallPWA />
          <Footer />
        </div>
      </DataProvider>
    </ThemeProvider>
  );
}

export default App;